function.arguments:
{"script":"realpath /working > target_path.txt
find /working -exec stat -c "%n %F" {} + > recursive_listing.txt
awk -F' ' '{
    path=$1;
    n=split(path, a, "/");
    basename=a[n];
    if(basename=="workspace") print $0;
}' recursive_listing.txt > candidates.txt
cat candidates.txt"}
